SELECT ?point ?label ?ts WHERE {
  ?point ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?ts .
  FILTER(str(?point) LIKE "%SupplyFan%")
  OPTIONAL { ?point rdfs:label ?label }
}

